from sympy import prod
# Each sign is an incremental stage derivative, in the order in the corresponding physical path.
cases = [('12.85(a)', 'vout↑ → iD2↑ → M2 드레인↓ → NMOS M3 소스 출력↓', [1, -1, 1], '음귀환'), ('12.85(b)', 'vout↑ → iD2↑ → M2 드레인↓ → PMOS M3 공급 전류↑ → vout↑', [1, -1, -1, 1], '양귀환'), ('12.85(c)', 'iout↑ → R1의 상단↑ → iD2↑ → M2 드레인↓ → PMOS M3의 공급 전류↑ → iout↑', [1, 1, -1, -1, 1], '양귀환'), ('12.85(d)', 'iout↑ → R1의 상단↑ → iD2↑ → M2 드레인↓ → NMOS M3 소스 출력↓ → iout↓', [1, 1, -1, 1, 1], '음귀환'), ('12.85(e)', 'vout↑ → 분압점↑ → iD2↑ → M2 드레인 vout↓', [1, 1, -1], '음귀환'), ('12.85(f)', 'vout↑ → iD2↑ → PMOS 전류거울 M4/M3의 공급 전류↑ → R1의 vout↑', [1, 1, 1], '양귀환'), ('12.86(a)', 'vout↑ → 고정 Vin에서 M1의 VGS↑ → iD1↑ → M1 드레인↓ → NMOS M2 소스 출력↓', [1, 1, -1, 1], '음귀환'), ('12.86(b)', 'vout↑ → iD1↑ → M1 드레인↓ → PMOS M2 공급 전류↑ → vout↑', [1, -1, -1, 1], '양귀환'), ('12.86(c)', 'iout↑ → R1 상단↑ → iD1↑ → M1 드레인↓ → PMOS M2 공급 전류↑ → iout↑', [1, 1, -1, -1, 1], '양귀환'), ('12.86(d)', 'vout↑ → iD1↑ → PMOS 전류거울 M3/M2의 출력 공급 전류↑ → R1의 vout↑', [1, 1, 1], '양귀환'), ('12.87(a)', 'vout↑ → NMOS M2의 공급 전류↑ → X↑ → CS M1의 드레인 전압↓', [1, 1, -1], '음귀환'), ('12.87(b)', 'vout↑ → PMOS M2의 공급 전류↓ → X↓ → CS M1의 드레인 전압↑', [-1, 1, -1], '양귀환'), ('12.87(c)', 'vout↑ → 고정 게이트 PMOS M2의 VSG↑ → X로의 공급 전류↑ → X↑ → CS M1의 드레인 전압↓', [1, 1, 1, -1], '음귀환'), ('12.87(d)', 'vout↑ → PMOS M2 공급 전류↓ → X(소스1)↓ → 고정 게이트 M1의 VGS↑ → vout↓', [-1, 1, -1, -1], '음귀환'), ('12.88(a)', 'vout↑ → RF를 통해 베이스로 주입되는 전류↑ → Q1의 컬렉터 전류↑ → vout↓', [1, 1, -1], '음귀환'), ('12.88(b)', 'vout↑ → RF를 통해 M1 게이트 노드로 주입되는 전류↑ → M1 게이트 전압↑ → iD2↓ → M2 드레인↑ → NMOS M3 소스 출력↑', [1, 1, -1, -1, 1], '양귀환')]
for key, chain, incremental_signs, expected in cases:
    sign = prod(incremental_signs)
    result = '음귀환' if sign < 0 else '양귀환'
    assert expected == result
    print(key, chain, '=>', sign, result)
